#!/usr/bin/env python3
"""Build crawlable Korean/English homepages from the public Excel-derived data."""
import json,html,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
def esc(x):return html.escape(str(x or ''),quote=True)
def text(x):return re.sub(r'&lt;br\s*/?&gt;','<br>',esc(x),flags=re.I)
def build():
 d=json.loads((SITE/'data/site-data.json').read_text(encoding='utf8'))
 visuals=d['visuals']
 for lang in ('ko','en'):
  def t(ko,en):return ko if lang=='ko' else en
  def v(o,k):return o.get(k+'_'+lang) or o.get(k+'_ko','')
  def setting(k,fallback=''):return d['settings'].get(k,{}).get(lang,fallback)
  def link(slug):return './'+slug+('-en' if lang=='en' else '')+'.html'
  def image(key,cls='',eager=False):
   m=visuals.get(key)
   if not m:raise ValueError('Image map entry required for '+key)
   return f'<img class="{cls}" src="./{esc(m["src"])}" alt="{esc(v(m,"alt"))}" style="object-position:{esc(m["position"])}" width="960" height="660" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
  home='./index-en.html' if lang=='en' else './index.html'
  navs=[('#about',t('회사소개','Company')),('#business',t('사업영역','Business')),('#products',t('소싱 품목','Sourcing')),(link('services'),t('서비스','Services')),('./pricing.html'+('?lang=en' if lang=='en' else ''),t('요금 안내','Pricing'))]
  nav=''.join(f'<a href="{url}">{label}</a>' for url,label in navs)
  choices={
   'business-development':('market-research',t('시장 조사 · 진출 전략 · 사업성 검토','Market research · Entry strategy · Business feasibility')),
   'trade-sourcing':('supply-chain',t('공급사 발굴 · 견적 비교 · 샘플 조율','Supplier discovery · RFQ comparison · Sampling')),
   'supply-chain':('supply-chain',t('수입·물류 파트너 · 납기 · 운영 조율','Import and logistics partners · Delivery coordination')),
   'strategic-partnerships':('buyer-development',t('해외 브랜드 진출 · 사업 제휴 · 프로젝트','Brand expansion · Partnerships · Project support'))}
  cards=''
  for i,s in enumerate(d['services'],1):
   target,scope=choices.get(s['id'],('services',v(s,'description')))
   cards+=f'''<a class="business-card" href="{link(target)}"><div class="business-photo">{image(s['id'])}<span class="photo-num">0{i}</span></div><div class="business-card-body"><div><span class="card-kicker">{esc(s['sector']).upper()}</span><h3>{esc(v(s,'title'))}</h3><p>{esc(scope)}</p></div><span class="card-arrow" aria-hidden="true">↗</span></div></a>'''
  products=''
  for p in d['products']:
   if p['sku'] not in visuals:raise ValueError('Visible product needs a matching image: '+p['sku'])
   catlabel={'Interior':t('실내 용품','Interior'),'Care':t('관리 용품','Care'),'Film':t('필름','Film')}.get(p['category'],p['category'])
   products+=f'''<article class="catalog-card" data-product-category="{esc(p['category'])}"><div class="catalog-art">{image(p['sku'])}</div><div class="catalog-body"><span class="card-kicker">{esc(catlabel)}</span><h3>{esc(v(p,'name'))}</h3><p>{esc(v(p,'description'))}</p><a href="#contact" data-product="{esc(v(p,'name'))}">{t('소싱 상담','Discuss sourcing')} <span aria-hidden="true">↗</span></a></div></article>'''
  steps=''.join(f'<article class="step-card"><span class="step-number">0{i}</span><h3>{esc(v(x,"title"))}</h3><p>{esc(v(x,"description"))}</p></article>' for i,x in enumerate(d['steps'],1))
  partners=''.join(f'<button type="button" class="partner-card" data-partner="{esc(p["id"])}"><span>{esc(v(p,"title"))}</span><span aria-hidden="true">↗</span></button>' for p in d['partners'])
  opts=f'<option value="">{t("선택하세요","Choose a category")}</option>'+''.join(f'<option value="{esc(p["id"])}">{esc(v(p,"title"))}</option>' for p in d['partners'])
  fields=[('company',t('회사명','Company'),'organization','text',True),('name',t('담당자','Contact name'),'name','text',True),('email',t('업무 이메일','Business email'),'email','email',True),('region',t('대상 국가','Target market'),'off','text',False)]
  fieldshtml=''.join(f'<label><span>{label}{" *" if req else ""}</span><input name="{name}" type="{typ}" autocomplete="{ac}" maxlength="150" {"required" if req else ""}></label>' for name,label,ac,typ,req in fields)
  service_short=''.join(f'<a href="{link(slug)}">{ko if lang=="ko" else en}<span>↗</span></a>' for slug,ko,en in [('overseas-sales','해외영업 대행','Overseas sales'),('market-research','해외시장조사','Market research'),('buyer-development','바이어 발굴','Buyer development'),('export-consulting','수출 컨설팅','Export consulting'),('supply-chain','소싱·공급망','Sourcing & supply'),('franchise-development','프랜차이즈 사업개발','Franchise development')])
  price=lambda key: '₩'+format(int(next(x['starting_price_krw'] for x in d['pricing'] if x['id']==key)),',')
  title=t('해외영업·해외시장조사·소싱 | Y2C HOLDINGS','International Sales, Research & Sourcing | Y2C HOLDINGS')
  desc=t('주식회사 와이투씨홀딩스. 해외영업 대행, 해외시장조사, 바이어 발굴, 무역·소싱, 공급망과 해외 프랜차이즈 사업개발.','Y2C Holdings supports international sales, market research, buyer development, sourcing, supply chains and franchise expansion.')
  canonical='https://y2choldings.co.kr/'+('index-en.html' if lang=='en' else '')
  label_free=t('무료 사전진단','Free readiness check')
  page=f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f3ef">
<title>{title}</title><meta name="description" content="{desc}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="ko" href="https://y2choldings.co.kr/"><link rel="alternate" hreflang="en" href="https://y2choldings.co.kr/index-en.html"><link rel="alternate" hreflang="x-default" href="https://y2choldings.co.kr/">
<meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://y2choldings.co.kr/assets/images/hero-operations.webp"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="./assets/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=Noto+Sans+KR:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="./assets/corporate.css"><script src="./assets/app.js" defer></script>
<script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'Organization','name':'주식회사 와이투씨홀딩스','alternateName':'Y2C HOLDINGS','url':'https://y2choldings.co.kr/','logo':'https://y2choldings.co.kr/assets/y2c-logo.png','email':setting('contact_email')},ensure_ascii=False)}</script></head>
<body><a class="skip" href="#main">{t('본문으로 이동','Skip to content')}</a>
<header class="site-header" id="top"><div class="container nav-row"><a class="logo" href="{home}"><img src="./assets/y2c-logo.png" width="34" height="40" alt="Y2C HOLDINGS"><span>Y2C HOLDINGS</span></a><nav class="desktop-nav" aria-label="{t('주 메뉴','Main navigation')}">{nav}</nav><div class="nav-end"><div class="lang-toggle"><a href="./index.html" data-lang="ko" class="{'active' if lang=='ko' else ''}" aria-label="한국어">KR</a><span>/</span><a href="./index-en.html" data-lang="en" class="{'active' if lang=='en' else ''}" aria-label="English">EN</a></div><a class="nav-contact" href="#contact">{t('문의하기','Contact')} ↗</a><button id="menuBtn" class="menu-button" aria-controls="mobileNav" aria-expanded="false" aria-label="{t('메뉴 열기','Open menu')}"><span></span><span></span></button></div></div><nav id="mobileNav" class="mobile-nav" hidden>{nav}<a href="#contact">{t('문의하기','Contact')}</a></nav></header>
<main id="main"><section class="hero" aria-labelledby="heroTitle"><div class="container hero-layout"><div class="hero-copy"><span class="eyebrow"><i></i> GLOBAL BUSINESS PARTNER</span><h1 id="heroTitle">{text(setting('hero_title'))}</h1><p class="hero-deck">{text(setting('hero_description'))}</p><div class="hero-actions"><a class="button dark" href="#contact">{t('프로젝트 상담','Discuss a project')} <span>↗</span></a><a class="text-link" href="#business">{t('사업영역 보기','Explore our business')} <span>↓</span></a></div><div class="hero-foot"><span>KOREA — NORTH AMERICA</span><span>BUSINESS / RESEARCH / TRADE</span></div></div><figure class="hero-visual">{image('hero','',True)}<figcaption><span>FROM PLAN TO EXECUTION</span><span>{t('공급·현장 실행 분야 연출 이미지','Supply coordination · illustrative scene')}</span></figcaption></figure></div></section>
<section class="intro-section" id="about"><div class="container intro-grid"><span class="section-label">01 — ABOUT Y2C</span><div><h2>{text(setting('about_title'))}</h2><p>{text(setting('about_description'))}</p></div><div class="intro-note"><span>INDEPENDENT.<br>CONNECTED.<br>PRACTICAL.</span><small>{t('산업보다 업무에 집중합니다.','Focused on the work, not a single industry.')}</small></div></div></section>
<section class="section business" id="business"><div class="container"><div class="section-heading"><div><span class="section-label">02 — OUR BUSINESS</span><h2>{t('무엇을 함께할 수 있을까요.','Work we can move forward.')}</h2></div><a class="text-link" href="{link('services')}">{t('전체 서비스','All services')} ↗</a></div><div class="service-list" id="servicesGrid">{cards}</div><div class="service-shortcuts">{service_short}</div></div></section>
<section class="industries" id="expertise"><div class="container"><span class="section-label">FOCUS AREAS</span><div class="industry-grid"><article><span>01 / AUTOMOTIVE</span><h3>{t('자동차·애프터마켓','Automotive & aftermarket')}</h3><p>{t('딜러십·유통 채널을 위한 제품 소싱','Product sourcing for dealership and distribution channels')}</p></article><article><span>02 / FOOD & FRANCHISE</span><h3>{t('식품·프랜차이즈','Food & franchise')}</h3><p>{t('해외 운영 파트너와 공급망 검토','Operating partners and overseas supply planning')}</p></article><article><span>03 / CROSS-INDUSTRY</span><h3>{t('제조·소비재·유통','Manufacturing & consumer goods')}</h3><p>{t('제품과 시장에 맞는 기업 간 거래 개발','B2B opportunities tailored to products and markets')}</p></article></div></div></section>
<section class="section catalog" id="products"><div class="container"><div class="section-heading"><div><span class="section-label">03 — SOURCING COLLECTION</span><h2>{t('좋은 제품을, 맞는 시장으로.','The right products. The right market.')}</h2></div><p>{t('북미 딜러십 공급을 검토하는 소싱 품목입니다.','Sourcing categories for North American dealerships.')}</p></div><div class="catalog-toolbar"><div id="productFilters" class="catalog-filters"></div><span id="productCount" class="catalog-count">{len(d['products'])} {t('개 품목','items')}</span></div><div class="catalog-grid" id="productsGrid">{products}</div><p class="catalog-disclaimer">{t('제품 사진은 품목 이해를 위한 연출 예시입니다. 실제 공급 사양·차종 적합성·원산지·인증·가격은 개별 확인하며, 재고 또는 납품 확약을 의미하지 않습니다.','Product images are illustrative references, not confirmed SKUs or inventory. Specifications, fitment, origin, compliance and prices require individual confirmation.')}</p></div></section>
<section class="research-section" id="research"><div class="container research-grid"><div><span class="section-label">04 — RESEARCH & INSIGHT</span><h2>{t('필요한 깊이만큼,<br>명확하게 조사합니다.','The right depth.<br>A clearer next step.')}</h2><p>{t('무료 준비도 점검부터 맞춤형 시장조사까지.<br>범위와 산출물을 먼저 정합니다.','From a free readiness check to tailored research.<br>Scope and deliverables come first.')}</p><a class="text-link" href="./pricing.html{('?lang=en' if lang=='en' else '')}">{t('전체 요금 안내','View all pricing')} ↗</a></div><div class="research-options"><a href="./free-report.html{('?lang=en' if lang=='en' else '')}"><span><small>01 / READINESS</small><strong>{label_free}</strong><em>{t('선택형 체크리스트 · 즉시 확인','Dropdown checklist · Instant result')}</em></span><b>₩0 <i>↗</i></b></a><a href="./quick-report.html{('?lang=en' if lang=='en' else '')}"><span><small>02 / QUICK RESEARCH</small><strong>{t('선택형 간편 조사','Quick research')}</strong><em>{t('필요한 조사항목만 선택','Choose the research modules you need')}</em></span><b>₩199,000~ <i>↗</i></b></a><a href="./pricing.html{('?lang=en' if lang=='en' else '')}"><span><small>03 / CUSTOM RESEARCH</small><strong>{t('전문 시장조사 보고서','Professional research')}</strong><em>{t('시장·경쟁·진입전략 분석','Market, competition and entry strategy')}</em></span><b>{price('essential')}~ <i>↗</i></b></a><p class="research-note">{t('유료 서비스는 부가세 별도. 최종 범위와 금액은 계약으로 확정합니다.','Paid services exclude VAT. Final scope and fees are agreed in writing.')}</p></div></div></section>
<section class="section approach" id="approach"><div class="container"><div class="section-heading"><div><span class="section-label">05 — HOW WE WORK</span><h2>{t('하나의 프로젝트, 명확한 진행.','One project. A clear process.')}</h2></div></div><div class="steps-grid" id="stepsGrid">{steps}</div></div></section>
<section class="partners" id="partners"><div class="container"><div class="partners-title"><span class="section-label">PARTNERSHIPS</span><h2>{t('함께할 기업을 기다립니다.','Let’s build the next connection.')}</h2></div><div id="partnersGrid" class="partner-grid">{partners}</div></div></section>
<section class="section contact" id="contact"><div class="container contact-grid"><div class="contact-heading"><span class="section-label">06 — GET IN TOUCH</span><h2>{text(setting('section_contact_title'))}</h2><p>{esc(setting('section_contact_intro'))}</p><a class="contact-email" href="mailto:{esc(setting('contact_email'))}">{esc(setting('contact_email'))} ↗</a><div class="contact-location">BUSAN, KOREA<br><span>{t('미국·캐나다 중심의 해외사업 협력','Cross-border business with a North American focus')}</span></div></div><form id="contactForm" class="contact-form"><div class="form-grid">{fieldshtml}<label><span>{t('협업 분야','Partnership type')} *</span><select name="partner_type" id="partnerType" required>{opts}</select></label><label><span>{t('관심 업무·제품','Service or product')}</span><input name="interest" maxlength="140"></label></div><label class="message-field"><span>{t('프로젝트 내용','Project details')} *</span><textarea name="message" rows="4" maxlength="2400" required placeholder="{t('목표와 필요한 업무를 간단히 알려주세요.','Tell us your objective and what you need.')}" ></textarea></label><div class="form-final"><label class="consent"><input type="checkbox" name="consent" required><span><a href="./privacy.html">{t('개인정보 안내','Privacy information')}</a>{t('를 확인했습니다.',' reviewed.')}</span></label><button class="button dark" id="submitBtn" type="submit"><span>{t('메일로 문의하기','Prepare an email')}</span> ↗</button></div><p class="form-note" id="formNote">{t('메일 앱이 열립니다. 직접 전송을 눌러야 발송되며, 이 화면에서 자동 접수되지 않습니다.','Opens your mail app. You must press Send there; this form does not submit automatically.')}</p><p id="formStatus" role="status" aria-live="polite"></p><div id="formFallback" hidden><textarea id="preparedText" readonly rows="7" aria-label="{t('문의 내용','Prepared inquiry')}"></textarea><button type="button" id="copyBtn">{t('내용 복사','Copy message')}</button></div></form></div></section>
</main><footer class="site-footer"><div class="container"><div class="footer-row"><a class="logo" href="{home}"><img src="./assets/y2c-logo.png" width="30" height="36" alt="Y2C HOLDINGS"><span>Y2C HOLDINGS</span></a><div><a href="{link('services')}">{t('서비스','Services')}</a><a href="./pricing.html">{t('요금 안내','Pricing')}</a><a href="./privacy.html">{t('개인정보 안내','Privacy')}</a><a href="./admin.html">{t('관리자','Admin')}</a></div></div><p class="footer-disclosure">{t('이미지는 사업·제품을 설명하기 위한 연출 예시이며, 실제 Y2C 직원·고객사·사업장·납품 실적 사진이 아닙니다.','Visuals illustrate business and product concepts; they do not depict actual Y2C staff, clients, premises or completed supply contracts.')}</p><div class="footer-bottom"><span>{t('주식회사 와이투씨홀딩스 · 부산광역시','Y2C HOLDINGS CO., LTD. · BUSAN, KOREA')}</span><span>© <span id="copyrightYear">2026</span> Y2C HOLDINGS</span></div></div></footer><div id="loadError" hidden role="alert">{t('일부 데이터를 불러오지 못했습니다. 페이지를 새로고침해주세요.','Some data could not be loaded. Please refresh the page.')}</div></body></html>'''
  (SITE/('index-en.html' if lang=='en' else 'index.html')).write_text(page,encoding='utf8')
 print('Built static KR/EN homepages with exact category/image mapping')
if __name__=='__main__':build()
